INSERT INTO questions (id, module, theme_id, passage_id, media_id, difficulty, question_type, statement, explanation, is_active, created_at, updated_at, status, tcf_sub_theme, audio_mode, competence_code) VALUES ('55555555-0009-0000-0000-000000000013','TCF','22222222-0000-0000-0000-000000000003',NULL,NULL,'B1','STRUCTURE','Complétez : « Quand je suis arrivé chez lui, il ___ déjà la télévision. »','On a deux actions au passé : une action ponctuelle terminée (« je suis arrivé », passé composé) et une action en cours à ce moment-là (« regardait », imparfait pour décrire un arrière-plan, une situation déjà installée). « A regardé » exprimerait une action ponctuelle. « Regardera » est au futur. « Regarderait » est au conditionnel.','true','2026-05-27 17:40:30.147221+02','2026-05-27 17:40:30.147221+02','ACTIVE',NULL,NULL,'struct_imparfait_vs_passe_compose');
INSERT INTO questions (id, module, theme_id, passage_id, media_id, difficulty, question_type, statement, explanation, is_active, created_at, updated_at, status, tcf_sub_theme, audio_mode, competence_code) VALUES ('55555555-0009-0000-0000-000000000014','TCF','22222222-0000-0000-0000-000000000003',NULL,NULL,'B1','STRUCTURE','Complétez : « C''est un film ___ tout le monde parle en ce moment. »','Le verbe « parler » se construit avec la préposition « de » : on parle DE quelque chose. Le pronom relatif qui remplace un complément introduit par « de » est « dont ». « Que » remplace un complément d''objet direct (sans préposition). « Qui » remplace un sujet. « Où » remplace un complément de lieu ou de temps.','true','2026-05-27 17:40:30.147221+02','2026-05-27 17:40:30.147221+02','ACTIVE',NULL,NULL,'struct_pronom_relatif_dont');
INSERT INTO questions (id, module, theme_id, passage_id, media_id, difficulty, question_type, statement, explanation, is_active, created_at, updated_at, status, tcf_sub_theme, audio_mode, competence_code) VALUES ('55555555-0009-0000-0000-000000000015','TCF','22222222-0000-0000-0000-000000000003',NULL,NULL,'B1','STRUCTURE','Complétez : « Si vous aviez plus de temps, vous ___ apprendre une nouvelle langue. »','La structure « Si + imparfait » dans la subordonnée appelle un conditionnel présent dans la principale → « pourriez ». « Pouvez » est un présent (incompatible avec une hypothèse irréelle). « Pouviez » est un imparfait (placé dans la principale, c''est incorrect). « Pourrez » est un futur (compatible seulement avec « si + présent »).','true','2026-05-27 17:40:30.147221+02','2026-05-27 17:40:30.147221+02','ACTIVE',NULL,NULL,'struct_hypothese_si_imparfait');
INSERT INTO questions (id, module, theme_id, passage_id, media_id, difficulty, question_type, statement, explanation, is_active, created_at, updated_at, status, tcf_sub_theme, audio_mode, competence_code) VALUES ('55555555-0009-0000-0000-000000000016','TCF','22222222-0000-0000-0000-000000000003',NULL,NULL,'B1','STRUCTURE','Remplacez le complément : « — Tu veux du café ? — Oui, j''___ veux bien. »','« Du café » est un complément introduit par l''article partitif « du » : il se remplace par le pronom « en », qui reprend toute quantité indéterminée. « Le » et « la » remplacent des compléments définis (le café = ce café précis, pas une quantité non précisée). « Y » remplace un complément de lieu ou un complément introduit par la préposition « à ».','true','2026-05-27 17:40:30.147221+02','2026-05-27 17:40:30.147221+02','ACTIVE',NULL,NULL,'struct_pronom_en');
INSERT INTO questions (id, module, theme_id, passage_id, media_id, difficulty, question_type, statement, explanation, is_active, created_at, updated_at, status, tcf_sub_theme, audio_mode, competence_code) VALUES ('55555555-0010-0000-0000-000000000013','TCF','22222222-0000-0000-0000-000000000003',NULL,NULL,'B1','STRUCTURE','Complétez : « Quand je suis arrivé à la gare, le train ___ déjà parti depuis dix minutes. »','Pour exprimer une action antérieure à une autre action passée, on utilise le plus-que-parfait : « était parti » (auxiliaire « être » à l''imparfait + participe passé). « A parti » est incorrect (le verbe « partir » prend l''auxiliaire « être », pas « avoir »). « Partait » est un imparfait simple (action en cours, pas antérieure). « Est parti » est un passé composé.','true','2026-05-27 17:40:30.164849+02','2026-05-27 17:40:30.164849+02','ACTIVE',NULL,NULL,'struct_plus_que_parfait');
INSERT INTO questions (id, module, theme_id, passage_id, media_id, difficulty, question_type, statement, explanation, is_active, created_at, updated_at, status, tcf_sub_theme, audio_mode, competence_code) VALUES ('55555555-0010-0000-0000-000000000014','TCF','22222222-0000-0000-0000-000000000003',NULL,NULL,'B1','STRUCTURE','Complétez : « Il pleut beaucoup ce matin, ___ je vais prendre mon parapluie. »','On exprime ici une conséquence (action qui découle de la cause « il pleut »). « Donc » est un connecteur de conséquence, qui convient parfaitement. « Parce que » introduit une cause, pas une conséquence. « Mais » introduit une opposition. « Pourtant » introduit une concession (idée contraire à l''attente).','true','2026-05-27 17:40:30.164849+02','2026-05-27 17:40:30.164849+02','ACTIVE',NULL,NULL,'struct_connecteur_consequence');
INSERT INTO questions (id, module, theme_id, passage_id, media_id, difficulty, question_type, statement, explanation, is_active, created_at, updated_at, status, tcf_sub_theme, audio_mode, competence_code) VALUES ('55555555-0010-0000-0000-000000000015','TCF','22222222-0000-0000-0000-000000000003',NULL,NULL,'B1','STRUCTURE','Complétez : « Il faut que tu ___ ton dossier avant vendredi. »','L''expression « il faut que » exprime l''obligation et est toujours suivie du subjonctif. À la 2e personne du singulier du verbe « finir » au subjonctif présent : « finisses ». « Finis » est l''indicatif présent (ou impératif). « Finiras » est un futur. « Finirais » est un conditionnel. Aucun de ces temps ne s''emploie après « il faut que ».','true','2026-05-27 17:40:30.164849+02','2026-05-27 17:40:30.164849+02','ACTIVE',NULL,NULL,'struct_subjonctif_il_faut_que');
INSERT INTO questions (id, module, theme_id, passage_id, media_id, difficulty, question_type, statement, explanation, is_active, created_at, updated_at, status, tcf_sub_theme, audio_mode, competence_code) VALUES ('55555555-0010-0000-0000-000000000016','TCF','22222222-0000-0000-0000-000000000003',NULL,NULL,'B1','STRUCTURE','Mettez à la voix passive : « Le maire inaugure la nouvelle école. »','À la voix passive, le complément d''objet direct (« la nouvelle école ») devient sujet, et le sujet (« le maire ») devient complément d''agent introduit par « par ». Le verbe se conjugue avec « être » au même temps que le verbe actif (présent) → « est inaugurée » (accord au féminin singulier avec « école »). « Sera inaugurée » est un futur passif, « a été inaugurée » un passé composé passif, « est inauguré » manque l''accord au féminin.','true','2026-05-27 17:40:30.164849+02','2026-05-27 17:40:30.164849+02','ACTIVE',NULL,NULL,'struct_voix_passive');
INSERT INTO questions (id, module, theme_id, passage_id, media_id, difficulty, question_type, statement, explanation, is_active, created_at, updated_at, status, tcf_sub_theme, audio_mode, competence_code) VALUES ('55555555-0011-0000-0000-000000000013','TCF','22222222-0000-0000-0000-000000000003',NULL,NULL,'B1','STRUCTURE','Complétez avec une formule polie : « Bonjour, je ___ un café, s''il vous plaît. »','Pour exprimer une demande polie, on utilise le conditionnel présent : « je voudrais ». « Veux » (présent) est correct grammaticalement mais peu poli dans un contexte formel. « Voulais » est un imparfait (action habituelle ou en cours dans le passé, inadapté ici). « Aurais voulu » est un conditionnel passé, qui exprime un regret, pas une demande actuelle.','true','2026-05-27 17:40:30.178875+02','2026-05-27 17:40:30.178875+02','ACTIVE',NULL,NULL,'struct_conditionnel_politesse');
INSERT INTO questions (id, module, theme_id, passage_id, media_id, difficulty, question_type, statement, explanation, is_active, created_at, updated_at, status, tcf_sub_theme, audio_mode, competence_code) VALUES ('55555555-0011-0000-0000-000000000014','TCF','22222222-0000-0000-0000-000000000003',NULL,NULL,'B1','STRUCTURE','Transformez au discours indirect : Elle me demande : « Est-ce que tu viens ? »','Au discours indirect, on supprime les guillemets et on introduit la question par « si » (pour une question fermée totale, sans mot interrogatif). Les pronoms changent aussi : « tu viens » → « je viens » (du point de vue du locuteur rapporteur). « Que je viens » serait correct seulement pour une affirmation, pas pour une question. « Quand je viens » introduit une interrogation sur le moment, ce qui n''est pas le sens. « Pourquoi je viens » porte sur la cause.','true','2026-05-27 17:40:30.178875+02','2026-05-27 17:40:30.178875+02','ACTIVE',NULL,NULL,'struct_discours_indirect_present');
INSERT INTO questions (id, module, theme_id, passage_id, media_id, difficulty, question_type, statement, explanation, is_active, created_at, updated_at, status, tcf_sub_theme, audio_mode, competence_code) VALUES ('55555555-0011-0000-0000-000000000015','TCF','22222222-0000-0000-0000-000000000003',NULL,NULL,'B1','STRUCTURE','Complétez : « Je te prête mon livre ___ tu puisses le lire ce week-end. »','Quand le sujet de la principale (« je ») est différent de celui de la subordonnée (« tu »), on utilise « pour que » + subjonctif (« puisses »). « Pour » s''emploie avec un infinitif, mais seulement quand les deux sujets sont identiques. « Afin de » s''emploie aussi avec un infinitif (même contrainte). « Parce que » introduit une cause, pas un but.','true','2026-05-27 17:40:30.178875+02','2026-05-27 17:40:30.178875+02','ACTIVE',NULL,NULL,'struct_expression_but');
INSERT INTO questions (id, module, theme_id, passage_id, media_id, difficulty, question_type, statement, explanation, is_active, created_at, updated_at, status, tcf_sub_theme, audio_mode, competence_code) VALUES ('55555555-0011-0000-0000-000000000016','TCF','22222222-0000-0000-0000-000000000003',NULL,NULL,'B1','STRUCTURE','Remplacez le complément : « Je vais à la piscine. → J''___ vais. »','« À la piscine » est un complément de lieu introduit par « à ». Il se remplace par le pronom « y », qui reprend les compléments de lieu (où l''on est, où l''on va) ou les compléments introduits par « à ». « En » remplace un complément introduit par « de » ou un partitif. « Le » et « la » remplacent des compléments d''objet direct.','true','2026-05-27 17:40:30.178875+02','2026-05-27 17:40:30.178875+02','ACTIVE',NULL,NULL,'struct_pronom_y');
INSERT INTO questions (id, module, theme_id, passage_id, media_id, difficulty, question_type, statement, explanation, is_active, created_at, updated_at, status, tcf_sub_theme, audio_mode, competence_code) VALUES ('55555555-0012-0000-0000-000000000013','TCF','22222222-0000-0000-0000-000000000003',NULL,NULL,'B1','STRUCTURE','Complétez : « Le livre ___ tu m''as offert est passionnant. »','Dans la subordonnée relative, « tu » est sujet et « le livre » est COD du verbe « as offert » (tu as offert quoi ? le livre). Le pronom relatif qui remplace un COD est « que ». « Qui » remplacerait un sujet (le livre qui est sur la table). « Dont » remplace un complément introduit par « de ». « Où » remplace un complément de lieu ou de temps.','true','2026-05-27 17:40:30.194289+02','2026-05-27 17:40:30.194289+02','ACTIVE',NULL,NULL,'struct_relatif_qui_que');
INSERT INTO questions (id, module, theme_id, passage_id, media_id, difficulty, question_type, statement, explanation, is_active, created_at, updated_at, status, tcf_sub_theme, audio_mode, competence_code) VALUES ('55555555-0012-0000-0000-000000000014','TCF','22222222-0000-0000-0000-000000000003',NULL,NULL,'B1','STRUCTURE','Complétez : « J''ai rencontré Marie ___ trois ans, dans un café. »','L''action est ponctuelle et terminée (« j''ai rencontré ») : on situe le moment dans le passé avec « il y a ». « Depuis » indique une durée qui continue jusqu''au présent (incompatible avec une action ponctuelle au passé composé). « Pendant » indique une durée délimitée d''une action. « Pour » indique une durée prévue à l''avance.','true','2026-05-27 17:40:30.194289+02','2026-05-27 17:40:30.194289+02','ACTIVE',NULL,NULL,'struct_depuis_il_y_a_pendant');
INSERT INTO questions (id, module, theme_id, passage_id, media_id, difficulty, question_type, statement, explanation, is_active, created_at, updated_at, status, tcf_sub_theme, audio_mode, competence_code) VALUES ('55555555-0012-0000-0000-000000000015','TCF','22222222-0000-0000-0000-000000000003',NULL,NULL,'B1','STRUCTURE','Complétez : « Si tu travailles bien cette année, tu ___ ton examen sans difficulté. »','La structure « si + présent » dans la subordonnée appelle un futur simple dans la principale → « auras ». « As » est un présent (incompatible avec une projection dans l''avenir). « Aurais » est un conditionnel (compatible avec « si + imparfait », pas « si + présent »). « Avais » est un imparfait.','true','2026-05-27 17:40:30.194289+02','2026-05-27 17:40:30.194289+02','ACTIVE',NULL,NULL,'struct_hypothese_si_present');
INSERT INTO questions (id, module, theme_id, passage_id, media_id, difficulty, question_type, statement, explanation, is_active, created_at, updated_at, status, tcf_sub_theme, audio_mode, competence_code) VALUES ('55555555-0012-0000-0000-000000000016','TCF','22222222-0000-0000-0000-000000000003',NULL,NULL,'B1','STRUCTURE','Remplacez le complément : « Je téléphone à ma mère. → Je ___ téléphone. »','Le verbe « téléphoner » se construit avec « à » : on téléphone À quelqu''un. « À ma mère » est donc un COI (complément d''objet indirect). Le pronom COI de la 3e personne du singulier (masculin ou féminin) est « lui ». « La » est un COD féminin singulier (je la vois). « Elle » est un pronom tonique (sujet ou complément après préposition). « Leur » est COI pluriel (à eux/à elles).','true','2026-05-27 17:40:30.194289+02','2026-05-27 17:40:30.194289+02','ACTIVE',NULL,NULL,'struct_pronom_coi');
INSERT INTO questions (id, module, theme_id, passage_id, media_id, difficulty, question_type, statement, explanation, is_active, created_at, updated_at, status, tcf_sub_theme, audio_mode, competence_code) VALUES ('55555555-0013-0000-0000-000000000017','TCF','22222222-0000-0000-0000-000000000003',NULL,NULL,'B1','STRUCTURE','Complétez : « Il est important que vous ___ à l''heure pour l''entretien. »','L''expression « il est important que » exprime la nécessité et est suivie du subjonctif. À la 2e personne du pluriel du verbe « être » au subjonctif présent : « soyez ». « Êtes » est l''indicatif présent. « Serez » est un futur simple. « Seriez » est un conditionnel présent. Aucun de ces temps ne s''emploie après « il est important que ».','true','2026-05-27 17:40:30.209527+02','2026-05-27 17:40:30.209527+02','ACTIVE',NULL,NULL,'struct_subjonctif_important_que');
INSERT INTO questions (id, module, theme_id, passage_id, media_id, difficulty, question_type, statement, explanation, is_active, created_at, updated_at, status, tcf_sub_theme, audio_mode, competence_code) VALUES ('55555555-0013-0000-0000-000000000018','TCF','22222222-0000-0000-0000-000000000003',NULL,NULL,'B1','STRUCTURE','Complétez : « Je me souviens du jour ___ nous nous sommes rencontrés. »','Le pronom relatif « où » remplace ici un complément de temps (« le jour »). Il s''emploie aussi pour les compléments de lieu. « Que » remplace un complément d''objet direct, ce que « le jour » n''est pas ici. « Quand » est un mot interrogatif ou un adverbe, pas un pronom relatif dans cette construction. « Dont » remplace un complément introduit par « de ».','true','2026-05-27 17:40:30.209527+02','2026-05-27 17:40:30.209527+02','ACTIVE',NULL,NULL,'struct_relatif_ou_temps');
INSERT INTO questions (id, module, theme_id, passage_id, media_id, difficulty, question_type, statement, explanation, is_active, created_at, updated_at, status, tcf_sub_theme, audio_mode, competence_code) VALUES ('55555555-0013-0000-0000-000000000019','TCF','22222222-0000-0000-0000-000000000003',NULL,NULL,'B1','STRUCTURE','Complétez : « J''ai trouvé ce travail ___ mon ami Paul, qui m''a recommandé. »','« Grâce à » introduit une cause à effet POSITIF (un coup de pouce, une aide qui produit un bon résultat). « À cause de » introduit aussi une cause, mais à effet négatif (à cause de la pluie, le concert a été annulé). « En raison de » est neutre et plus formel. « Malgré » introduit une concession, pas une cause.','true','2026-05-27 17:40:30.209527+02','2026-05-27 17:40:30.209527+02','ACTIVE',NULL,NULL,'struct_cause_grace_a');
INSERT INTO questions (id, module, theme_id, passage_id, media_id, difficulty, question_type, statement, explanation, is_active, created_at, updated_at, status, tcf_sub_theme, audio_mode, competence_code) VALUES ('55555555-0013-0000-0000-000000000020','TCF','22222222-0000-0000-0000-000000000003',NULL,NULL,'B1','STRUCTURE','Complétez : « — Tu sais que Pierre a déménagé ? — Oui, je ___ sais. »','Le pronom « le » peut reprendre une proposition entière (ici : « que Pierre a déménagé »). On dit « je le sais » pour reprendre l''information. « La » serait un COD féminin singulier (incorrect ici). « Lui » est un pronom indirect (à lui/à elle). « Y » remplace un complément de lieu ou introduit par « à ».','true','2026-05-27 17:40:30.209527+02','2026-05-27 17:40:30.209527+02','ACTIVE',NULL,NULL,'struct_pronom_le_neutre');
INSERT INTO questions (id, module, theme_id, passage_id, media_id, difficulty, question_type, statement, explanation, is_active, created_at, updated_at, status, tcf_sub_theme, audio_mode, competence_code) VALUES ('55555555-0023-0000-0000-000000000009','TCF','22222222-0000-0000-0000-000000000003',NULL,NULL,'B1','STRUCTURE','Complétez avec le temps qui convient : Quand Pierre ___ jeune, il ___ tous les étés à la mer.','Pour décrire un état et une habitude au passé, on utilise l''imparfait pour les deux : « était » (état) + « allait » (action répétée). La réponse C est correcte. « A été... est allé » utilise le passé composé pour deux verbes : cela décrirait deux actions ponctuelles, pas un état + une habitude. « Était... est allé » mixe imparfait et passé composé : le second verbe devrait aussi être à l''imparfait pour exprimer l''habitude. « Était... a été » utilise l''imparfait puis le passé composé du mauvais verbe (« être » au lieu d''« aller »).','true','2026-05-27 17:40:30.278936+02','2026-05-27 17:40:30.278936+02','ACTIVE',NULL,NULL,'struct_imparfait_passe_compose');
INSERT INTO questions (id, module, theme_id, passage_id, media_id, difficulty, question_type, statement, explanation, is_active, created_at, updated_at, status, tcf_sub_theme, audio_mode, competence_code) VALUES ('55555555-0023-0000-0000-000000000010','TCF','22222222-0000-0000-0000-000000000003',NULL,NULL,'B1','STRUCTURE','Complétez avec le futur simple : Quand tu ___ à Paris, n''oublie pas de visiter le Louvre.','Avec « quand » suivi d''un futur dans la principale (« n''oublie pas »), le verbe est au futur simple : « viendras ». La réponse B est correcte. « Viens » est le présent : ne respecte pas la concordance du futur. « Es venu » est le passé composé : action déjà accomplie. « Venais » est l''imparfait : action passée habituelle. Le piège classique en B1 : après « quand » de sens futur, on utilise le futur (pas le présent comme en anglais).','true','2026-05-27 17:40:30.278936+02','2026-05-27 17:40:30.278936+02','ACTIVE',NULL,NULL,'struct_futur_simple');
INSERT INTO questions (id, module, theme_id, passage_id, media_id, difficulty, question_type, statement, explanation, is_active, created_at, updated_at, status, tcf_sub_theme, audio_mode, competence_code) VALUES ('55555555-0023-0000-0000-000000000011','TCF','22222222-0000-0000-0000-000000000003',NULL,NULL,'B1','STRUCTURE','Complétez avec la forme la plus polie : Bonjour, je ___ un café, s''il vous plaît.','Au restaurant ou dans un commerce, on utilise le conditionnel pour faire une demande polie : « voudrais ». La réponse C est correcte. « Veux » est le présent : grammaticalement correct mais brusque, peu poli. « Voulais » est l''imparfait : utilisable mais moins courant dans cette situation. « Aurais voulu » est le conditionnel passé : c''est trop fort, on l''utilise pour exprimer un regret. Le piège : tous sont grammaticaux, seul le conditionnel présent est adapté à la situation.','true','2026-05-27 17:40:30.278936+02','2026-05-27 17:40:30.278936+02','ACTIVE',NULL,NULL,'struct_conditionnel_present');
INSERT INTO questions (id, module, theme_id, passage_id, media_id, difficulty, question_type, statement, explanation, is_active, created_at, updated_at, status, tcf_sub_theme, audio_mode, competence_code) VALUES ('55555555-0023-0000-0000-000000000012','TCF','22222222-0000-0000-0000-000000000003',NULL,NULL,'B1','STRUCTURE','Complétez avec le pronom relatif correct : C''est le livre ___ j''ai acheté hier à la librairie.','Le pronom relatif remplace « le livre » qui est COD du verbe « acheté » → « que ». La réponse B est correcte. « Qui » est sujet : il faudrait que le livre fasse l''action, or ici c''est moi qui ai acheté. « Où » indique un lieu ou un temps : aucun des deux ici. « Dont » remplace un complément introduit par « de » (j''ai parlé du livre → dont j''ai parlé). Le piège fréquent en B1 : confondre qui (sujet) et que (objet).','true','2026-05-27 17:40:30.278936+02','2026-05-27 17:40:30.278936+02','ACTIVE',NULL,NULL,'struct_pronom_relatif_simple');
INSERT INTO questions (id, module, theme_id, passage_id, media_id, difficulty, question_type, statement, explanation, is_active, created_at, updated_at, status, tcf_sub_theme, audio_mode, competence_code) VALUES ('55555555-0023-0000-0000-000000000013','TCF','22222222-0000-0000-0000-000000000003',NULL,NULL,'B1','STRUCTURE','Complétez avec l''accord correct du verbe « écouter » : Les chansons que j''ai ___ hier étaient magnifiques.','Avec l''auxiliaire « avoir », le participe passé s''accorde avec le COD s''il est placé AVANT le verbe. Ici, « les chansons » (féminin pluriel) est antéposé au verbe → « écoutées ». La réponse C est correcte. « Écouté » est le masculin singulier (forme par défaut quand pas d''accord). « Écoutés » est le masculin pluriel : faux genre. « Écoutée » est le féminin singulier : faux nombre. Ce point est typiquement B1.','true','2026-05-27 17:40:30.278936+02','2026-05-27 17:40:30.278936+02','ACTIVE',NULL,NULL,'struct_accord_participe_avoir');
INSERT INTO questions (id, module, theme_id, passage_id, media_id, difficulty, question_type, statement, explanation, is_active, created_at, updated_at, status, tcf_sub_theme, audio_mode, competence_code) VALUES ('55555555-0023-0000-0000-000000000014','TCF','22222222-0000-0000-0000-000000000003',NULL,NULL,'B1','STRUCTURE','Complétez avec l''expression de temps correcte : Pierre habite à Lyon ___ trois ans, et il s''y plaît beaucoup.','Pour exprimer une action commencée dans le passé et qui continue dans le présent, on utilise « depuis ». La réponse C est correcte. « Il y a » s''utilise pour une action terminée à un moment précis du passé (« il y a 3 ans, il a déménagé »). « Pendant » exprime une durée terminée (« il a habité à Lyon pendant 3 ans, puis il est parti »). « Pour » exprime une durée prévue dans le futur (« il part à Lyon pour 3 ans »).','true','2026-05-27 17:40:30.278936+02','2026-05-27 17:40:30.278936+02','ACTIVE',NULL,NULL,'struct_expressions_temps');
INSERT INTO questions (id, module, theme_id, passage_id, media_id, difficulty, question_type, statement, explanation, is_active, created_at, updated_at, status, tcf_sub_theme, audio_mode, competence_code) VALUES ('55555555-0023-0000-0000-000000000015','TCF','22222222-0000-0000-0000-000000000003',NULL,NULL,'B1','STRUCTURE','Complétez avec le superlatif correct : Marie est ___ étudiante de la classe.','Le superlatif de supériorité se construit avec « la plus + adjectif » devant un nom féminin singulier. La réponse B est correcte. « La meilleur » est piégeux : « meilleur » est le superlatif de « bon », mais l''accord féminin manque (il faut « la meilleure »). « Plus bonne » est incorrect : « bonne » devient « meilleure » au superlatif. « Très intelligente » exprime un haut degré mais n''est pas un superlatif (pas de comparaison avec un groupe).','true','2026-05-27 17:40:30.278936+02','2026-05-27 17:40:30.278936+02','ACTIVE',NULL,NULL,'struct_superlatif');
INSERT INTO questions (id, module, theme_id, passage_id, media_id, difficulty, question_type, statement, explanation, is_active, created_at, updated_at, status, tcf_sub_theme, audio_mode, competence_code) VALUES ('55555555-0023-0000-0000-000000000016','TCF','22222222-0000-0000-0000-000000000003',NULL,NULL,'B1','STRUCTURE','Complétez avec le gérondif : Il écoute la radio ___ sa voiture.','Le gérondif exprime la simultanéité avec « en + participe présent ». Forme : « en + radical + -ant ». Pour « conduire » → « en conduisant ». La réponse B est correcte. « En conduit » mélange « en » avec le participe passé : forme inexistante. « Conduisant » sans « en » est un participe présent : il faudrait une virgule et un sens différent. « À conduire » avec l''infinitif est une autre construction (« il a appris à conduire ») qui ne convient pas ici.','true','2026-05-27 17:40:30.278936+02','2026-05-27 17:40:30.278936+02','ACTIVE',NULL,NULL,'struct_gerondif');
